mapper.select:
select c.id as commentId, c.root_id as rootId, c.parent_id as parentId, c.post_id as postId, p.creator_id as postPublisherId, p.status as postStatus, c.is_audit as isAudit, c.type as commentType, c.content as content, c.create_time as createTime, c.is_top as isTop, c.status as status, c.ip_location as ipLocation, c.client_type as client_type, c.reply_count as replyCount, c.hot_score as hotScore, c.user_id as publisherId, c.extra as extra from comments c left join posts p on p.id = c.post_id
c.post_id = #{postId}
and ((c.hot_score < #{lastHotScoreCursor}) or (c.hot_score = #{lastHotScoreCursor} and c.id < #{lastCommentIdCursor}))
and c.root_id is null and c.parent_id is null and c.is_audit = 1 and c.status = 1
order by c.is_top desc, c.hot_score desc,c.id desc limit #{limit}

select c.id as commentId, c.root_id as rootId, c.user_id as publisherId, c.parent_id as parentId, c.post_id as postId, p.creator_id as postPublisherId, p.status as postStatus, c.is_audit as isAudit, c.type as commentType, c.content as content, c.create_time as createTime, c.is_top as isTop, c.status as status, c.ip_location as ipLocation, c.client_type as client_type, c.reply_count as replyCount, c.extra as extra from comments c left join posts p on p.id = c.post_id
c.post_id = #{postId}
and c.id < #{cursor}
and c.root_id = #{rootId} and c.is_audit = 1 and c.status = 1
order by c.id desc limit #{limit}

SELECT c.id, c.hot_score AS hotScore, c.create_time as createTime, c.reply_count AS replyCount, c.like_count AS likeCount, c.update_time as updateTime FROM comments c WHERE c.status = 1 AND c.update_time >= #{deadLine} AND c.parent_id IS NULL AND c.root_id IS NULL
AND (c.update_time, c.id) > (#{lastUpdateTime}, #{lastId})
ORDER BY c.update_time , c.id LIMIT 1000;
